// Wrap your router's link once. `href` stays a path; this stand-in only stops the browser navigating.
const RouterLink: LinkComponent = ({ href, onClick, children, ...rest }) => (
  <a
    href={href}
    {...rest}
    onClick={(event) => {
      event.preventDefault();
      onClick?.(event);
