import { useMemo, useState } from 'react';
import { SplitBar } from '@punji/ui/bars';
import { Button } from '@punji/ui/button';
import { Card } from '@punji/ui/card';
import { KeyStats } from '@punji/ui/key-stats';
import { PageHeader } from '@punji/ui/layout';
import { MarketHeatmap, heatmapItemsFromQuotes } from '@punji/ui/market-heatmap';
import { MarketIndices } from '@punji/ui/market-indices';
import { MarketMovers, type MoverKind } from '@punji/ui/market-movers';
import { MarketStatus, getMarketSession, nepseSchedule } from '@punji/ui/market-status';
import { ShareBar, SHARE_TONES, type ShareItem } from '@punji/ui/meter';
import { MoneyDisplay } from '@punji/ui/money-display';
import { formatCompactMoney, nepalMoneyConfig } from '@punji/ui/money';
import { StockTable, sortQuotes, type QuoteSort } from '@punji/ui/stock-table';
import { marketIndices, quotes as closing, sampleNow } from '../../sample.ts';
import './screen.css';

// A live market board. Every panel reads one array of quotes; "Receive a tick" stands in for your socket and hands
// the panels new props (prices move by 50 paisa steps). The table flashes the cells that changed (live).
const npr = nepalMoneyConfig();
const session = getMarketSession(sampleNow, nepseSchedule);

export default function Example() {
  const [step, setStep] = useState(0);
  const [sort, setSort] = useState<QuoteSort>({ key: 'turnover', dir: 'desc' });
  const [tab, setTab] = useState<MoverKind>('gainers');
  const quotes = useMemo(
    () =>
      closing.map((q, i) => {
        const ltp = q.ltp === null || step === 0 ? q.ltp : q.ltp + BigInt(((step * (i + 3)) % 9) - 4) * 50n;
        return { ...q, ltp, turnover: ltp === null || q.volume === null ? null : ltp * BigInt(q.volume) };
      }),
    [step],
  );
  const breadth = useMemo(() => {
    let up = 0,
      flat = 0,
      down = 0;
    for (const q of quotes) {
      if (q.ltp === null || q.previousClose === null) continue;
      if (q.ltp > q.previousClose) up += 1;
      else if (q.ltp < q.previousClose) down += 1;
      else flat += 1;
    }
    return { up, flat, down };
  }, [quotes]);
  const turnover = quotes.reduce((sum, q) => sum + (q.turnover ?? 0n), 0n);
  const volume = quotes.reduce((sum, q) => sum + (q.volume ?? 0), 0);
  // Turnover by sector as whole percents; the largest sector absorbs the rounding so the bar adds up to 100.
  const sectors = useMemo(() => {
    const by = new Map<string, bigint>();
    for (const q of quotes) by.set(q.sector, (by.get(q.sector) ?? 0n) + (q.turnover ?? 0n));
    const total = [...by.values()].reduce((a, b) => a + b, 0n) || 1n;
    const rows = [...by].toSorted((a, b) => (b[1] > a[1] ? 1 : -1)).map(([label, t]) => ({ label, pct: Number((t * 100n) / total) }));
    rows[0]!.pct += 100 - rows.reduce((a, r) => a + r.pct, 0);
    return rows.map((r, i): ShareItem => ({ key: r.label, label: r.label, pct: r.pct, tone: SHARE_TONES[i] ?? 'rest' }));
  }, [quotes]);

  return (
    <div className="sc-mkt">
      <PageHeader
        headingLevel={3}
        title="Market"
        stamp={<MarketStatus session={session} market="NEPSE" />}
        actions={
          <Button variant="secondary" size="sm" onClick={() => setStep((s) => s + 1)}>
            Receive a tick
          </Button>
        }
      />

      <MarketIndices indices={marketIndices} label="NEPSE indices" variant="cards" asOf="Index values at the 14 Nov close" />

      <div className="sc-mkt-row">
        <Card title="Breadth" description={`${quotes.length} listed companies on this board`} headingLevel={3} stretch>
          <div className="sc-mkt-breadth">
            <SplitBar
              parts={[
                { key: 'up', value: breadth.up, tone: 'gain', label: `${breadth.up} up` },
                { key: 'flat', value: breadth.flat, tone: 'neutral', label: `${breadth.flat} unchanged` },
                { key: 'down', value: breadth.down, tone: 'loss', label: `${breadth.down} down` },
              ]}
            />
            <ShareBar
              items={sectors}
              label={`Turnover by sector: ${sectors.map((x) => `${x.label} ${x.pct} percent`).join(', ')}`}
              legend="list"
              foot="Share of today’s turnover by sector."
            />
            <KeyStats
              cols={3}
              label="Session totals"
              empty="Not published"
              items={[
                { label: 'Turnover', value: <MoneyDisplay value={turnover} preset={npr} compact /> },
                { label: 'Shares traded', value: volume.toLocaleString('en-IN') },
                { label: 'Ticks received', value: String(step) },
              ]}
            />
          </div>
        </Card>
        <Card label="Turnover heatmap" stretch>
          <MarketHeatmap
            items={heatmapItemsFromQuotes(quotes, 'turnover')}
            label="NEPSE turnover heatmap"
            sizeLabel="Turnover"
            formatSize={(v) => formatCompactMoney(BigInt(Math.round(v)), npr)}
          />
        </Card>
      </div>

      <div className="sc-mkt-main">
        <Card title="Live prices" description="Sorted by turnover; choose a column to sort" headingLevel={3} flush>
          <StockTable
            caption="NEPSE live prices, NPR"
            quotes={sortQuotes(quotes, sort)}
            sort={sort}
            onSortChange={setSort}
            columns={['symbol', 'ltp', 'change', 'volume', 'turnover', 'trend']}
            live
            maxHeight={440}
          />
        </Card>
        <Card title="Movers" description="By percent change and turnover" headingLevel={3}>
          <MarketMovers quotes={quotes} label="Movers" tab={tab} onTabChange={setTab} limit={5} footer="Synthetic data, not market data." />
        </Card>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { SplitBar } from '@punji/ui/bars';
import { Button } from '@punji/ui/button';
import { percentageChange } from '@punji/ui/calculations';
import { Card } from '@punji/ui/card';
import { CheckList, CheckRow } from '@punji/ui/check-row';
import { CompanySearch } from '@punji/ui/company-search';
import { StateGlyph } from '@punji/ui/inline-state';
import { KeyStats } from '@punji/ui/key-stats';
import { MoneyDisplay } from '@punji/ui/money-display';
import { formatMoney, nepalMoneyConfig } from '@punji/ui/money';
import { PriceChange } from '@punji/ui/price-change';
import { PriceLimitIndicator, circuitLimits } from '@punji/ui/price-limit';
import { StatusPill } from '@punji/ui/status-pill';
import { Watchlist } from '@punji/ui/watchlist';
import { quotes, symbols } from '../../sample.ts';
import './screen.css';

// A watchlist with price alerts. The list is yours: Watchlist only asks to reorder or remove, CompanySearch asks to
// add. Choosing a symbol opens its panel: the quote, how far it sits inside today's circuit band and its alerts.
const npr = nepalMoneyConfig();
const bySymbol = new Map(quotes.map((q) => [q.symbol, q]));

interface Alert {
  id: string;
  symbol: string;
  side: 'above' | 'below';
  /** Paisa. */
  target: bigint;
}
const ALERTS: Alert[] = [
  { id: 'a1', symbol: 'NABIL', side: 'above', target: 49_000n },
  { id: 'a2', symbol: 'NABIL', side: 'below', target: 46_500n },
  { id: 'a3', symbol: 'UPPER', side: 'above', target: 39_500n },
  { id: 'a4', symbol: 'NICA', side: 'below', target: 52_000n },
  { id: 'a5', symbol: 'HDL', side: 'above', target: 220_000n },
];

export default function Example() {
  const [list, setList] = useState(['NABIL', 'NICA', 'UPPER', 'HDL', 'CHCL', 'NTC']);
  const [picked, setPicked] = useState('NABIL');
  const rows = list.map((s) => bySymbol.get(s)!).filter(Boolean);
  const quote = bySymbol.get(picked) ?? rows[0];
  const rose = rows.filter((q) => q.ltp !== null && q.previousClose !== null && q.ltp > q.previousClose).length;
  const fell = rows.filter((q) => q.ltp !== null && q.previousClose !== null && q.ltp < q.previousClose).length;
  const band = quote?.previousClose ? circuitLimits(quote.previousClose, '0.10') : null;
  const alerts = ALERTS.filter((a) => a.symbol === quote?.symbol);

  return (
    <div className="sc-wl">
      <div className="sc-wl-head">
        <div className="sc-wl-title">
          <h3>Watchlist</h3>
          <StatusPill size="sm">{rows.length} companies</StatusPill>
        </div>
        <div className="sc-wl-add">
          <CompanySearch
            options={symbols.filter((o) => !list.includes(o.symbol))}
            label="Add a company"
            hideLabel
            placeholder="Add a company to the watchlist"
            size="sm"
            shortcut={null}
            clearOnOpen
            onOpen={(symbol) => {
              setList((current) => (current.includes(symbol) ? current : [...current, symbol]));
              setPicked(symbol);
            }}
            sub={(o) => o.name}
            none={(q) => `No company matches “${q}”.`}
            testId="wl-add"
            optionTestId="wl-add-option"
          />
        </div>
      </div>

      <div className="sc-wl-grid">
        <div className="sc-wl-list">
          <Card title="Today" description={`${rose} rose, ${fell} fell, ${rows.length - rose - fell} unchanged`} headingLevel={3}>
            <div className="sc-wl-stack">
              <SplitBar
                parts={[
                  { key: 'up', value: rose, tone: 'gain', label: `${rose} rose` },
                  { key: 'flat', value: rows.length - rose - fell, tone: 'neutral', label: `${rows.length - rose - fell} unchanged` },
                  { key: 'down', value: fell, tone: 'loss', label: `${fell} fell` },
                ]}
              />
              <Watchlist
                quotes={rows}
                label="My watchlist"
                showTrend
                renderSymbol={(q) => (
                  <Button variant="ghost" size="sm" aria-pressed={q.symbol === quote?.symbol} onClick={() => setPicked(q.symbol)}>
                    {q.symbol}
                  </Button>
                )}
                onReorder={(next) => setList(next)}
                onRemove={(symbol) => setList((current) => current.filter((s) => s !== symbol))}
                emptyTitle="Nothing on your watchlist"
                emptyBody="Search above to follow a company."
              />
            </div>
          </Card>
        </div>

        {quote && (
          <div className="sc-wl-side">
            <Card title={quote.symbol} description={quote.name} headingLevel={3} action={<StatusPill size="sm">{quote.sector}</StatusPill>}>
              <div className="sc-wl-stack">
                <div className="sc-wl-quote">
                  <span className="sc-wl-price">
                    <MoneyDisplay value={quote.ltp} preset={npr} />
                  </span>
                  <PriceChange current={quote.ltp} previous={quote.previousClose} preset={npr} />
                </div>
                <PriceLimitIndicator symbol={quote.symbol} ltp={quote.ltp} previousClose={quote.previousClose} lowerLimit={band?.lower} upperLimit={band?.upper} />
                <KeyStats
                  cols={2}
                  label={`${quote.symbol} session`}
                  empty="Not published"
                  items={[
                    { label: 'Turnover', value: <MoneyDisplay value={quote.turnover} preset={npr} compact /> },
                    { label: 'Volume', value: quote.volume?.toLocaleString('en-IN') ?? null },
                  ]}
                />
              </div>
            </Card>
            <Card
              title="Alerts"
              description={alerts.length ? `${alerts.length} set on ${quote.symbol}` : `None set on ${quote.symbol}`}
              headingLevel={3}
              action={
                <Button size="sm" variant="secondary">
                  New alert
                </Button>
              }
            >
              {alerts.length > 0 ? (
                <CheckList label={`Alerts on ${quote.symbol}`}>
                  {alerts.map((a) => {
                    const away = quote.ltp === null ? null : percentageChange(a.target, quote.ltp);
                    const hit = quote.ltp !== null && (a.side === 'above' ? quote.ltp >= a.target : quote.ltp <= a.target);
                    return (
                      <CheckRow
                        key={a.id}
                        icon={<StateGlyph name="bell" size={18} />}
                        tone={hit ? 'warn' : 'info'}
                        title={`${a.side === 'above' ? 'Rises above' : 'Falls below'} ${formatMoney(a.target, npr)}`}
                        line={away === null ? 'No price yet' : `${Math.abs(away).toFixed(2)}% from the last price`}
                        status={hit ? { label: 'Triggered', tone: 'warn' } : { label: 'Waiting' }}
                      />
                    );
                  })}
                </CheckList>
              ) : (
                <p className="sc-wl-empty">Set a level and hear the moment {quote.symbol} reaches it.</p>
              )}
            </Card>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Button } from '@punji/ui/button';
import { CandlestickChart } from '@punji/ui/candlestick-chart';
import { Card } from '@punji/ui/card';
import { SegmentedControl } from '@punji/ui/controls';
import { DepthChart } from '@punji/ui/depth-chart';
import { KeyStats } from '@punji/ui/key-stats';
import { MarketStatus, getMarketSession, nepseSchedule } from '@punji/ui/market-status';
import { MoneyDisplay } from '@punji/ui/money-display';
import { nepalMoneyConfig } from '@punji/ui/money';
import { formatPrice, formatQuantity } from '@punji/ui/nepal/market-format';
import { OrderBookDepth } from '@punji/ui/order-book';
import { PriceChange } from '@punji/ui/price-change';
import { PriceLimitIndicator, circuitLimits } from '@punji/ui/price-limit';
import { StatusPill } from '@punji/ui/status-pill';
import { depthAsks, depthBids, nabilCandles, sampleNow } from '../../sample.ts';
import './screen.css';

// A stock page: the quote, the daily candles with volume and averages, today's session, the circuit band, the order
// book and its depth. Candles and book levels are display numbers (rupees); the quote is exact bigint paisa.
const npr = nepalMoneyConfig();
const paisa = (rupees: number) => BigInt(Math.round(rupees * 100));
const last = nabilCandles.at(-1)!;
const prev = nabilCandles.at(-2)!;
const ltp = paisa(last.close);
const previousClose = paisa(prev.close);
const band = circuitLimits(previousClose, '0.10');
const RANGES = { '1M': 22, '3M': 60 } as const;
type Range = keyof typeof RANGES;
const rs = (rupees: number) => `Rs ${formatPrice(rupees)}`;

export default function Example() {
  const [range, setRange] = useState<Range>('3M');
  const [watching, setWatching] = useState(false);
  const candles = nabilCandles.slice(-RANGES[range]);
  const high = Math.max(...candles.map((c) => c.high));
  const low = Math.min(...candles.map((c) => c.low));
  return (
    <div className="sc-sd">
      <div className="sc-sd-head">
        <div className="sc-sd-id">
          <div>
            <h3>NABIL</h3>
            <p>Nabil Bank Limited · Commercial banks</p>
          </div>
        </div>
        <div className="sc-sd-quote">
          <span className="sc-sd-price">
            <MoneyDisplay value={ltp} preset={npr} />
          </span>
          <PriceChange current={ltp} previous={previousClose} preset={npr} />
        </div>
        <div className="sc-sd-actions">
          <MarketStatus session={getMarketSession(sampleNow, nepseSchedule)} size="sm" />
          <Button variant="secondary" size="sm" aria-pressed={watching} onClick={() => setWatching((w) => !w)}>
            {watching ? 'Watching' : 'Watch'}
          </Button>
          <Button size="sm">Add transaction</Button>
        </div>
      </div>

      <KeyStats
        layout="strip"
        label="NABIL last session"
        empty="Not published"
        items={[
          { label: 'Open', value: rs(last.open) },
          { label: 'High', value: rs(last.high) },
          { label: 'Low', value: rs(last.low) },
          { label: 'Volume', value: last.volume === null ? null : formatQuantity(last.volume) },
          { label: `${range} range`, value: `${formatPrice(low)} – ${formatPrice(high)}` },
        ]}
      />

      <div className="sc-sd-grid">
        <div className="sc-sd-main">
          <Card
            title="Price"
            description={`Daily candles, last ${candles.length} sessions, with volume`}
            headingLevel={3}
            action={
              <SegmentedControl<Range>
                label="Chart period"
                prefix="sc-sd-range"
                size="sm"
                value={range}
                onChange={setRange}
                options={(Object.keys(RANGES) as Range[]).map((value) => ({ value, label: value }))}
              />
            }
          >
            <CandlestickChart
              label={`NABIL, ${candles.length} daily candles with volume`}
              candles={candles}
              averages={[
                { type: 'sma', window: 10 },
                { type: 'ema', window: 20 },
              ]}
              height={300}
            />
          </Card>
          <Card title="Fundamentals" description="Latest published quarter" headingLevel={3}>
            <KeyStats
              cols={3}
              label="NABIL fundamentals"
              empty="Not published"
              items={[
                { label: 'EPS', value: '38.20', sub: 'Q1 2082/83, annualised' },
                { label: 'P/E', value: '12.8' },
                { label: 'Book value', value: 'Rs 214.10' },
                { label: 'Dividend yield', value: null },
                { label: 'Paid-up capital', value: 'Rs 27.06 Arba' },
                { label: 'Listed shares', value: '27,05,72,411' },
              ]}
            />
          </Card>
        </div>
        <div className="sc-sd-side">
          <Card title="Circuit band" description="±10% of the previous close" headingLevel={3}>
            <PriceLimitIndicator symbol="NABIL" ltp={ltp} previousClose={previousClose} lowerLimit={band.lower} upperLimit={band.upper} />
          </Card>
          <Card title="Order book" description="Best five levels a side" headingLevel={3} action={<StatusPill size="sm">Delayed</StatusPill>}>
            <OrderBookDepth
              bids={depthBids}
              asks={depthAsks}
              levels={5}
              labels={{
                buyQty: 'Buy qty',
                bid: 'Bid',
                ask: 'Ask',
                sellQty: 'Sell qty',
                caption: 'Order book for NABIL',
                buyTotal: (pct, qty) => `Buy ${pct} · ${qty}`,
                sellTotal: (pct, qty) => `Sell ${pct} · ${qty}`,
              }}
            />
          </Card>
          <Card title="Depth" description="Cumulative quantity, ten levels a side" headingLevel={3}>
            <DepthChart label="NABIL order book depth" bids={depthBids} asks={depthAsks} height={200} />
          </Card>
        </div>
      </div>
    </div>
  );
}

import { Breakdown, BreakdownRow } from '@punji/ui/breakdown';
import { Button } from '@punji/ui/button';
import { applyRate } from '@punji/ui/calculations';
import { Card } from '@punji/ui/card';
import { FinancialTable, type FinancialColumn } from '@punji/ui/financial';
import { KeyStats } from '@punji/ui/key-stats';
import { MeterBar } from '@punji/ui/meter';
import { MoneyDisplay } from '@punji/ui/money-display';
import { nepalMoneyConfig } from '@punji/ui/money';
import { formatBSDate, gregorianToBS } from '@punji/ui/nepal/calendar';
import { PaymentStatus } from '@punji/ui/payment-status';
import { DataRow, DataRows } from '@punji/ui/rows';
import './screen.css';

// A VAT invoice. Every amount is bigint paisa: line totals are quantity × rate, VAT is applyRate at 13% with
// half-up rounding, and the balance is the total less the payments recorded. The layout prints on one A4 page.
const npr = nepalMoneyConfig();
const money = (minor: bigint) => <MoneyDisplay value={minor} preset={npr} display="none" />;

interface Line {
  id: string;
  item: string;
  detail: string;
  quantity: bigint;
  /** Paisa per unit. */
  rate: bigint;
}
const LINES: Line[] = [
  { id: 'l1', item: 'A4 copier paper, 80 gsm', detail: 'Box of 5 reams', quantity: 40n, rate: 285_000n },
  { id: 'l2', item: 'Ledger books, 200 pages', detail: 'Hard bound, ruled', quantity: 25n, rate: 64_000n },
  { id: 'l3', item: 'Toner cartridge, 85A', detail: 'Compatible', quantity: 6n, rate: 345_000n },
  { id: 'l4', item: 'Delivery within the valley', detail: 'Kathmandu, Lalitpur, Bhaktapur', quantity: 1n, rate: 50_000n },
];
const lineTotal = (l: Line) => l.quantity * l.rate;
const subtotal = LINES.reduce((sum, l) => sum + lineTotal(l), 0n);
const discount = applyRate(subtotal, '0.05', 'half-up');
const taxable = subtotal - discount;
const vat = applyRate(taxable, '0.13', 'half-up');
const total = taxable + vat;
const PAYMENTS = [{ id: 'p1', label: 'Bank transfer, NIC Asia', date: { year: 2025, month: 11, day: 5 }, amount: 10_000_000n }];
const paid = PAYMENTS.reduce((sum, p) => sum + p.amount, 0n);
const balance = total - paid;
const paidPct = Number((paid * 100n) / total);

const issued = { year: 2025, month: 10, day: 29 };
const due = { year: 2025, month: 11, day: 28 };
const bs = (d: { year: number; month: number; day: number }) => formatBSDate(gregorianToBS(d));
const ad = (d: { year: number; month: number; day: number }) =>
  new Date(Date.UTC(d.year, d.month - 1, d.day)).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });

const columns: FinancialColumn<Line>[] = [
  // Quantity and rate sit under the item, so the table keeps two columns and fits a phone.
  {
    key: 'item',
    label: 'Item',
    rowHeader: true,
    render: (l) => (
      <span className="sc-inv-item">
        <b>{l.item}</b>
        <small>
          {l.quantity.toLocaleString('en-IN')} × {money(l.rate)} · {l.detail}
        </small>
      </span>
    ),
  },
  { key: 'amount', label: 'Amount', num: true, render: (l) => money(lineTotal(l)) },
];

export default function Example() {
  return (
    <div className="sc-inv">
      <div className="sc-inv-bar">
        <div className="sc-inv-title">
          <h3>Invoice INV-2082-0147</h3>
          <PaymentStatus status="partial" />
        </div>
        <div className="sc-inv-actions">
          <Button variant="secondary" size="sm">
            Download PDF
          </Button>
          <Button variant="secondary" size="sm">
            Send reminder
          </Button>
          <Button size="sm">Record payment</Button>
        </div>
      </div>

      <div className="sc-inv-grid">
        <article className="sc-inv-paper" aria-label="Invoice INV-2082-0147">
          <header className="sc-inv-head">
            <div>
              <p className="sc-inv-from">Himalayan Stationers Pvt. Ltd.</p>
              <p className="sc-inv-muted">New Road, Kathmandu · PAN 301234567</p>
            </div>
            <p className="sc-inv-kind">Tax invoice</p>
          </header>
          <KeyStats
            cols={3}
            label="Invoice details"
            empty="Not set"
            items={[
              { label: 'Billed to', value: 'Sagarmatha Traders', sub: 'Butwal · PAN 609876543' },
              { label: 'Issued', value: bs(issued), sub: ad(issued) },
              { label: 'Due', value: bs(due), sub: `${ad(due)} · 30 days` },
            ]}
          />
          <FinancialTable caption="Invoice lines, NPR" columns={columns} rows={LINES} rowKey={(l) => l.id} emptyTitle="No lines on this invoice" />
          <div className="sc-inv-totals">
            <Breakdown>
              <BreakdownRow label="Subtotal" value={money(subtotal)} />
              <BreakdownRow label="Trade discount" note="5% of the subtotal" value={<>- {money(discount)}</>} tone="down" />
              <BreakdownRow label="Taxable amount" value={money(taxable)} />
              <BreakdownRow label="VAT" note="13% of the taxable amount" value={money(vat)} />
              <BreakdownRow label="Total" total value={<MoneyDisplay value={total} preset={npr} />} />
            </Breakdown>
          </div>
          <p className="sc-inv-muted sc-inv-foot">Pay to Himalayan Stationers Pvt. Ltd., NIC Asia Bank, current account. Quote INV-2082-0147 as the reference.</p>
        </article>

        <aside className="sc-inv-side" aria-label="Payment">
          <Card title="Balance due" description={`Due ${bs(due)}`} headingLevel={3}>
            <div className="sc-inv-stack">
              <p className="sc-inv-balance">
                <MoneyDisplay value={balance} preset={npr} />
              </p>
              <MeterBar parts={[{ value: paidPct, tone: 'gain' }]} max={100} label={`${paidPct}% paid`} />
              <DataRows label="Payment summary">
                <DataRow label="Invoice total" value={money(total)} />
                {PAYMENTS.map((p) => (
                  <DataRow key={p.id} label={p.label} note={bs(p.date)} value={<>- {money(p.amount)}</>} />
                ))}
                <DataRow label="Balance" total value={money(balance)} />
              </DataRows>
            </div>
          </Card>
        </aside>
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { transactionsToCsv } from '@punji/ui/banking';
import { BankAccountCard } from '@punji/ui/bank-account-card';
import { Button } from '@punji/ui/button';
import { Card } from '@punji/ui/card';
import { SegmentedControl } from '@punji/ui/controls';
import { downloadText } from '@punji/ui/download';
import { CSV_MIME } from '@punji/ui/export';
import { Field } from '@punji/ui/fields';
import { FinancialSummary } from '@punji/ui/financial';
import { MoneyDisplay } from '@punji/ui/money-display';
import { nepalMoneyConfig } from '@punji/ui/money';
import { TransactionList } from '@punji/ui/transaction-list';
import { accounts, transactions } from '../../sample.ts';
import './screen.css';

// A bank statement. The summary is computed from the entries (bigint paisa): money in, money out, and the opening and
// closing balances as the bank stated them. Filters and the AD/BS switch only change what the list shows; the CSV is
// exactly the rows on screen, with formula text neutralised.
const npr = nepalMoneyConfig();
// The fixture's formula-text row belongs to the CSV safety example; a statement screen would not show it.
const entries = transactions.filter((t) => !t.counterparty.startsWith('='));
const settled = entries.filter((t) => t.status === 'completed');
const moneyIn = settled.reduce((sum, t) => (t.amount > 0n ? sum + t.amount : sum), 0n);
const moneyOut = settled.reduce((sum, t) => (t.amount < 0n ? sum - t.amount : sum), 0n);
const oldest = entries.at(-1)!;
const opening = (oldest.balance ?? 0n) - oldest.amount;
const closing = entries[0]!.balance ?? null;

type Flow = 'all' | 'in' | 'out';
type Calendar = 'ad' | 'bs';

export default function Example() {
  const [flow, setFlow] = useState<Flow>('all');
  const [calendar, setCalendar] = useState<Calendar>('bs');
  const [query, setQuery] = useState('');
  const shown = useMemo(() => {
    const q = query.trim().toLowerCase();
    return entries.filter(
      (t) => (flow === 'all' || (flow === 'in' ? t.amount > 0n : t.amount < 0n)) && (!q || `${t.counterparty} ${t.reference} ${t.category ?? ''}`.toLowerCase().includes(q)),
    );
  }, [flow, query]);
  const csv = () => downloadText('statement-nov-2025.csv', transactionsToCsv(shown, { currency: 'NPR', balance: true }), CSV_MIME);

  return (
    <div className="sc-bs">
      <FinancialSummary
        label="Statement summary, 9 to 14 November 2025"
        metrics={[
          { id: 'opening', label: 'Opening balance', value: <MoneyDisplay value={opening} preset={npr} />, note: '9 Nov' },
          { id: 'in', label: 'Money in', value: <MoneyDisplay value={moneyIn} preset={npr} />, note: `${settled.filter((t) => t.amount > 0n).length} credits` },
          { id: 'out', label: 'Money out', value: <MoneyDisplay value={moneyOut} preset={npr} />, note: `${settled.filter((t) => t.amount < 0n).length} debits` },
          { id: 'closing', label: 'Closing balance', value: <MoneyDisplay value={closing} preset={npr} />, note: '14 Nov, as stated' },
        ]}
      />

      <div className="sc-bs-grid">
        <div className="sc-bs-side">
          <BankAccountCard
            {...accounts.savings}
            balanceToggle
            defaultBalanceHidden={false}
            headingLevel={3}
            actions={
              <Button size="sm" variant="secondary">
                Transfer
              </Button>
            }
          />
        </div>
        <Card
          title="Transactions"
          description="Savings account, 9 to 14 November 2025"
          headingLevel={3}
          action={
            <Button size="sm" variant="secondary" onClick={csv}>
              Download CSV
            </Button>
          }
        >
          <div className="sc-bs-stack">
            <div className="sc-bs-filters">
              <div className="sc-bs-search">
                <Field label="Search transactions" hideLabel size="md" placeholder="Search payee, reference or category" value={query} onChange={setQuery} />
              </div>
              <SegmentedControl<Flow>
                label="Direction"
                prefix="sc-bs-flow"
                size="sm"
                value={flow}
                onChange={setFlow}
                options={[
                  { value: 'all', label: 'All' },
                  { value: 'in', label: 'Money in' },
                  { value: 'out', label: 'Money out' },
                ]}
              />
              <SegmentedControl<Calendar>
                label="Dates"
                prefix="sc-bs-cal"
                size="sm"
                value={calendar}
                onChange={setCalendar}
                options={[
                  { value: 'bs', label: 'BS' },
                  { value: 'ad', label: 'AD' },
                ]}
              />
            </div>
            <TransactionList transactions={shown} calendar={calendar} showBalance />
          </div>
        </Card>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { AccountNumber } from '@punji/ui/account-number';
import { BankAccountCard } from '@punji/ui/bank-account-card';
import { BeneficiarySelector } from '@punji/ui/beneficiary-selector';
import { Breakdown, BreakdownRow } from '@punji/ui/breakdown';
import { Button } from '@punji/ui/button';
import { Card } from '@punji/ui/card';
import { CurrencyInput } from '@punji/ui/currency-input';
import { Field } from '@punji/ui/fields';
import { InlineState } from '@punji/ui/inline-state';
import { MoneyDisplay } from '@punji/ui/money-display';
import { nepalMoneyConfig } from '@punji/ui/money';
import { PaymentReceipt } from '@punji/ui/payment-receipt';
import { PaymentTimeline } from '@punji/ui/payment-timeline';
import { StepList } from '@punji/ui/step-list';
import { accounts, beneficiaries, qrPlaceholderPath, receipt, timelineCompleted } from '../../sample.ts';
import './screen.css';

// Send money in four steps: payee, amount, review, receipt. Nothing is submitted: "Send" only moves to the receipt,
// built from the fixture's completed transfer. Your server confirms the payee, the fee and the transfer.
const npr = nepalMoneyConfig();
const FEE = 2_500n; // Rs 25.00, illustrative
const BALANCE = accounts.savings.balance;
const STEPS = [
  { title: 'Payee', body: 'Saved or recent' },
  { title: 'Amount', body: 'And a remark' },
  { title: 'Review', body: 'Check before sending' },
  { title: 'Receipt', body: 'Sent and recorded' },
];

export default function Example() {
  const [step, setStep] = useState(0);
  const [payee, setPayee] = useState<string | null>('b1');
  const [amount, setAmount] = useState('20000');
  const [minor, setMinor] = useState<bigint | null>(2_000_000n);
  const [remark, setRemark] = useState('Dashain gift');
  const to = beneficiaries.find((b) => b.id === payee);
  const over = minor !== null && minor + FEE > BALANCE;
  const amountError = minor === null ? undefined : minor <= 0n ? 'Enter an amount above zero.' : over ? 'More than the available balance, after the fee.' : undefined;
  const canContinue = step === 0 ? Boolean(to) : step === 1 ? minor !== null && !amountError : true;

  return (
    <div className="sc-pay">
      <div className="sc-pay-in">
        <div className="sc-pay-steps">
          <StepList title="Send money" eyebrow={`Step ${step + 1} of 4`} steps={STEPS} current={step} layout="rows" tone="plain" headingLevel={3} />
          <BankAccountCard {...accounts.savings} accountType="Paying from" headingLevel={4} />
        </div>

        <div className="sc-pay-panel">
          {step === 0 && (
            <Card title="Who are you paying?" description="From NIC Asia Bank savings" headingLevel={3}>
              <div className="sc-pay-stack">
                <BeneficiarySelector label="Pay to" beneficiaries={beneficiaries} value={payee} onChange={setPayee} />
              </div>
            </Card>
          )}

          {step === 1 && to && (
            <Card title={`How much to ${to.name}?`} description={`To ${to.institution}, from NIC Asia Bank savings`} headingLevel={3}>
              <div className="sc-pay-stack">
                <CurrencyInput
                  label="Amount"
                  preset={npr}
                  value={amount}
                  onValueChange={(change) => {
                    setAmount(change.value);
                    setMinor(change.minorUnits);
                  }}
                  hint={
                    <>
                      Available: <MoneyDisplay value={BALANCE} preset={npr} />
                    </>
                  }
                  error={amountError}
                />
                <Field label="Remark" value={remark} onChange={setRemark} hint="Shown on both statements" />
              </div>
            </Card>
          )}

          {step === 2 && to && minor !== null && (
            <Card title="Check before you send" description="You can still change anything" headingLevel={3}>
              <div className="sc-pay-stack">
                <div className="sc-pay-parties">
                  <div>
                    <p className="sc-pay-label">From</p>
                    <p className="sc-pay-name">{accounts.savings.holder}</p>
                    <p className="sc-pay-muted">{accounts.savings.institution}</p>
                    <AccountNumber value={accounts.savings.accountNumber} />
                  </div>
                  <div>
                    <p className="sc-pay-label">To</p>
                    <p className="sc-pay-name">{to.name}</p>
                    <p className="sc-pay-muted">{to.institution}</p>
                    <AccountNumber value={to.accountNumber} />
                  </div>
                </div>
                <Breakdown>
                  <BreakdownRow label="Amount" value={<MoneyDisplay value={minor} preset={npr} />} />
                  <BreakdownRow label="Transfer fee" note="Illustrative; your bank sets it" value={<MoneyDisplay value={FEE} preset={npr} />} />
                  <BreakdownRow label="Total from your account" total value={<MoneyDisplay value={minor + FEE} preset={npr} />} />
                </Breakdown>
                <InlineState icon="info" layout="row" role="status" title={`Remark: ${remark || 'none'}`} />
              </div>
            </Card>
          )}

          {step === 3 && (
            <div className="sc-pay-done">
              <PaymentReceipt
                {...receipt}
                amount={minor ?? receipt.amount}
                fees={FEE}
                to={{ name: to?.name ?? receipt.to.name, institution: to?.institution ?? receipt.to.institution, accountNumber: to?.accountNumber ?? receipt.to.accountNumber }}
                note={remark || undefined}
                timeZone="Asia/Kathmandu"
                qr={
                  <svg width="120" height="120" viewBox="0 0 20 20" role="img" aria-label="Payment QR code (placeholder)" fill="currentColor">
                    <path d={qrPlaceholderPath} />
                  </svg>
                }
              />
              <Card title="Progress" description="Times in Nepal time" headingLevel={3}>
                <PaymentTimeline steps={timelineCompleted} label="Transfer progress" timeZone="Asia/Kathmandu" />
              </Card>
            </div>
          )}

          <div className="sc-pay-nav">
            {step > 0 && step < 3 && (
              <Button variant="secondary" onClick={() => setStep((s) => s - 1)}>
                Back
              </Button>
            )}
            {step < 2 && (
              <Button disabled={!canContinue} onClick={() => setStep((s) => s + 1)}>
                Continue
              </Button>
            )}
            {step === 2 && <Button onClick={() => setStep(3)}>Send {minor !== null && <MoneyDisplay value={minor + FEE} preset={npr} />}</Button>}
            {step === 3 && (
              <Button variant="secondary" onClick={() => setStep(0)}>
                Send another
              </Button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Button } from '@punji/ui/button';
import { Card } from '@punji/ui/card';
import { JournalEntryView } from '@punji/ui/journal-entry';
import { PageHeader } from '@punji/ui/layout';
import { accountBalance, isBalanced, journalsToEntries, rollUp } from '@punji/ui/ledger';
import { LedgerTable } from '@punji/ui/ledger-table';
import { MetricRow, MetricTile } from '@punji/ui/metric-tile';
import { MoneyDisplay } from '@punji/ui/money-display';
import { nepalMoneyConfig } from '@punji/ui/money';
import { FinancialPeriodSelector, nepalFiscalMonthPeriods, nepalFiscalQuarterPeriods, nepalFiscalYearPeriods } from '@punji/ui/period-selector';
import { StatementTable } from '@punji/ui/statement-table';
import { StatusPill } from '@punji/ui/status-pill';
import { Tabs } from '@punji/ui/tabs';
import { TrialBalance } from '@punji/ui/trial-balance';
import { cashEntries, cashOpening, incomeStatement, journals, periodSpec, periods, unbalancedJournal } from '../../sample.ts';
import './screen.css';

// A small business's books. The tiles are display-rounded (compact); the reports below are exact. The figures come from the ledger helpers, exactly: the cash balance from the ledger,
// VAT payable from the posted journals, net profit from the rolled-up income statement. The period selector is
// wired to state only; filter your entries by the chosen period's dates.
const npr = nepalMoneyConfig();
